  *(u32*)((u8*)r1+8)=arg0->field_0x4C; *(u32*)((u8*)r1+0xC)=arg0->field_0x5C;
  *(s32*)((u8*)r1+0x10)=arg0->field_0x74;   // field_0x74 is s8 (target: ldrb; lsls #0x18; asrs #0x18)
