```c
typedef union { u64 q; struct { u32 lo; u32 hi; } w; } U64Union;
u64 sub_080C37B4(volatile u32 a0, volatile u32 a1, volatile u32 b0, volatile u32 b1) {
    u32 al, ah, bl, bh;
    u32 p00, p01, p10, p11;
    u32 mid, hi, lo;
    u32 t0 = a0, t1;
    U64Union u;
    al = t0 & 0xFFFF; ah = t0 >> 16;
    t1 = b0;
    bl = t1 & 0xFFFF; bh = t1 >> 16;
    p00 = al * bl; p01 = al * bh; p10 = ah * bl; p11 = ah * bh;
